const SV_REQUIRED_TABLES=['SafetyVote_Settings','SafetyVote_Campaigns','SafetyVote_CampaignVersions','SafetyVote_Stages','SafetyVote_EligibilityRules','SafetyVote_EligibilitySnapshots','SafetyVote_EligibleVoters','SafetyVote_CampaignRoles','SafetyVote_Files','SafetyVote_AuditLogs','SafetyVote_Questions','SafetyVote_Options','SafetyVote_Candidates','SafetyVote_Participation','SafetyVote_Ballots','SafetyVote_BallotIdentities','SafetyVote_BallotAnswers','SafetyVote_RequestKeys','SafetyVote_Submissions','SafetyVote_Nominations','SafetyVote_JuryCriteria','SafetyVote_JuryAssignments','SafetyVote_JuryScores','SafetyVote_ResultSnapshots','SafetyVote_ResultRows','SafetyVote_Certifications','SafetyVote_StageAdvancements','SafetyVote_Reports','SafetyVote_ExportJobs','SafetyVote_Notifications','SafetyVote_NotificationDeliveries'];
