function sv_actor(array $user): string{return trim((string)($user['id']??$user['EmployeeID']??''));}
function sv_role(array $user): string{return strtoupper(trim((string)($user['role']??$user['Role']??'')));}
function sv_schema_health(): array { $marks=implode(',',array_fill(0,count(SV_REQUIRED_TABLES),'?'));$rows=db_rows("SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ($marks)",SV_REQUIRED_TABLES);$found=[];foreach($rows as$row)$found[strtolower((string)$row['TABLE_NAME'])]=true;$missing=array_values(array_filter(SV_REQUIRED_TABLES,fn($name)=>!isset($found[strtolower($name)])));if($missing)return['ready'=>false,'missing'=>$missing,'contractVersion'=>SAFETY_VOTE_CONTRACT_VERSION,'schemaVersion'=>null,'moduleEnabled'=>false];$map=[];foreach(db_rows("SELECT SettingKey,SettingValue FROM SafetyVote_Settings WHERE SettingKey IN ('contract_version','schema_version','module_enabled')")as$row)$map[$row['SettingKey']]=(string)$row['SettingValue'];return['ready'=>($map['contract_version']??'')===SAFETY_VOTE_CONTRACT_VERSION&&in_array($map['schema_version']??'',[SV_SCHEMA_VERSION,'2026-10-08-phase6-r1','2026-10-08-phase7-r1'],true),'missing'=>[],'contractVersion'=>$map['contract_version']??null,'schemaVersion'=>$map['schema_version']??null,'moduleEnabled'=>($map['module_enabled']??'0')==='1']; }
function sv_require_schema(): array { try{$health=sv_schema_health();}catch(Throwable$error){json_response(['success'=>false,'code'=>'SAFETY_VOTE_SCHEMA_NOT_READY','message'=>'Unable to verify Safety Vote schema.'],503);}if(empty($health['ready']))json_response(['success'=>false,'code'=>'SAFETY_VOTE_SCHEMA_NOT_READY','message'=>'Safety Vote schema is not ready.','details'=>$health],503);return$health; }
function sv_has_permission(array$user,string$permission): bool {if(sv_role($user)==='ADMIN')return true;$override=db_row('SELECT granted FROM admin_userpermissions WHERE employee_id=? AND permission=? LIMIT 1',[sv_actor($user),$permission]);if($override)return(int)$override['granted']===1;$role=db_row('SELECT granted FROM admin_rolepermissions WHERE UPPER(role)=? AND permission=? LIMIT 1',[sv_role($user),$permission]);if($role&&(int)$role['granted']===1)return true;$admin=db_row('SELECT granted FROM admin_userpermissions WHERE employee_id=? AND permission=? LIMIT 1',[sv_actor($user),'SAFETY_VOTE_ADMIN']);return$admin&&(int)$admin['granted']===1;}
function sv_require_permission(array$user,string$permission): void {if(!sv_has_permission($user,$permission))json_response(['success'=>false,'code'=>'PERMISSION_DENIED','message'=>'Safety Vote permission is required.'],403);}
function sv_audit(array$user,string$action,string$targetType,string$targetId,string$detail,array$metadata=[],?int$campaignId=null,?int$versionId=null): void {try{db_execute('INSERT INTO SafetyVote_AuditLogs(CampaignID,CampaignVersionID,ActorEmployeeID,ActorRole,Action,TargetType,TargetID,StatusCode,BoundedDetail,MetadataJson,IPAddress,UserAgent) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[$campaignId,$versionId,sv_actor($user),sv_role($user),$action,$targetType,$targetId,200,sv_clean($detail,1000)?:null,json_encode($metadata,JSON_UNESCAPED_UNICODE),(string)($_SERVER['REMOTE_ADDR']??''),mb_substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,255)]);}catch(Throwable$error){error_log('[safety-vote] audit failed: '.$error->getMessage());}}
function sv_campaign_row(int$id,bool$lock=false): ?array {return db_row("SELECT c.*,v.VersionNo,v.ContractVersion,v.TemplateKey,v.CampaignType,v.PrivacyMode,v.TitleTh,v.TitleEn,v.Summary,v.Description,v.RulesText,v.TimeZone,v.OpenAt,v.CloseAt,v.ResultVisibility,v.PrivacyThreshold,v.Status VersionStatus,v.RowVersion VersionRowVersion FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.id=?".($lock?' FOR UPDATE':''),[$id]);}
function sv_master_projection(): array { $employees=db_rows('SELECT EmployeeID,EmployeeName,Department,Unit,Team,Position,Role,Password,MustChangePassword FROM employees ORDER BY EmployeeID');$departments=db_rows('SELECT id,Name,Status,is_safety_core FROM master_departments ORDER BY Name');$units=db_rows('SELECT id,name,department_id,short_code,sort_order FROM master_safetyunits ORDER BY department_id,sort_order,name');$positions=db_rows('SELECT id,Name FROM master_positions ORDER BY Name');$index=onboarding_build_master_index(['departments'=>$departments,'units'=>$units]);$key=fn($value)=>onboarding_normalize_name($value);$dept=[];$unit=[];$pos=[];foreach($departments as$row)$dept[$key($row['Name'])]=$row;foreach($units as$row)$unit[(string)$row['department_id']."\0".$key($row['name'])]=$row;foreach($positions as$row)$pos[$key($row['Name'])]=$row;$rows=[];foreach($employees as$row){$d=$dept[$key($row['Department'])]??null;$u=$d?($unit[(string)$d['id']."\0".$key($row['Unit'])]??null):null;$p=$pos[$key($row['Position'])]??null;try{$status=onboarding_resolve_with_index($row,$index);}catch(OnboardingResolutionException$error){$status=$error->reason;}$warnings=[];if(!$d)$warnings[]='DEPARTMENT_UNRESOLVED';if($d&&!$u&&array_filter($units,fn($x)=>(int)$x['department_id']===(int)$d['id']))$warnings[]='SAFETY_UNIT_UNRESOLVED';if(!$p)$warnings[]='POSITION_UNRESOLVED';$rows[]=['employeeId'=>(string)$row['EmployeeID'],'employeeName'=>(string)($row['EmployeeName']??''),'departmentId'=>$d?(int)$d['id']:null,'departmentName'=>(string)($row['Department']??''),'safetyUnitId'=>$u?(int)$u['id']:null,'safetyUnitName'=>(string)($row['Unit']??''),'positionId'=>$p?(int)$p['id']:null,'positionName'=>(string)($row['Position']??''),'role'=>(string)($row['Role']??''),'team'=>(string)($row['Team']??''),'masterPresent'=>true,'accountReady'=>$status===ONBOARDING_READY,'onboardingStatus'=>$status,'masterWarnings'=>$warnings];}return['employees'=>$rows,'departments'=>$departments,'units'=>$units,'positions'=>$positions]; }
function sv_private_dir(): string {$dir=dirname(__DIR__).DIRECTORY_SEPARATOR.'private'.DIRECTORY_SEPARATOR.'safety-vote';if(!is_dir($dir)&&!mkdir($dir,0770,true)&&!is_dir($dir))throw new RuntimeException('Unable to prepare Safety Vote private storage.');return$dir;}
function sv_file_mime(string$file): ?string {$head=(string)file_get_contents($file,false,null,0,16);if(strlen($head)>=3&&ord($head[0])===0xff&&ord($head[1])===0xd8&&ord($head[2])===0xff)return'image/jpeg';if(substr($head,0,8)==="\x89PNG\r\n\x1a\n")return'image/png';if(substr($head,0,4)==='RIFF'&&substr($head,8,4)==='WEBP')return'image/webp';if(substr($head,0,5)==='%PDF-')return'application/pdf';return null;}

