    if($campaign!==null&&$method==='DELETE'){sv_require_permission($user,'SAFETY_VOTE_MANAGE');$id=sv_positive_int($campaign['id']);$body=json_body();$reason=sv_clean($body['reason']??'',500);if(!$id||!$reason)json_response(['success'=>false,'code'=>'VALIDATION_FAILED','message'=>'Campaign ID and void reason are required.'],400);$pdo=db();$pdo->beginTransaction();try{$row=sv_campaign_row($id,true);if(!$row){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);}if($row['Status']!=='Draft'||$row['VersionStatus']!=='Draft'){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_STATE_CONFLICT','message'=>'Only Draft campaigns can be voided.'],409);}$pdo->prepare("UPDATE SafetyVote_Campaigns SET Status='Voided',VoidedAt=NOW(),VoidedBy=?,VoidReason=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?")->execute([sv_actor($user),$reason,sv_actor($user),$id]);$pdo->prepare("UPDATE SafetyVote_CampaignVersions SET Status='Voided',UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?")->execute([sv_actor($user),$row['CurrentVersionID']]);$pdo->commit();sv_audit($user,'SAFETY_VOTE_CAMPAIGN_VOID','SafetyVote_Campaign',(string)$id,$reason,[],$id,(int)$row['CurrentVersionID']);json_response(['success'=>true,'data'=>['id'=>$id,'status'=>'Voided']]);}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}}
    $masterMap=['/safety-vote/admin/master/departments'=>'departments','/safety-vote/admin/master/safety-units'=>'units','/safety-vote/admin/master/positions'=>'positions'];if($method==='GET'&&isset($masterMap[$path])){sv_require_permission($user,'SAFETY_VOTE_MANAGE');$data=sv_master_projection();json_response(['success'=>true,'data'=>$data[$masterMap[$path]]]);}
