    $upload=route_params($path,'/safety-vote/admin/campaigns/:id/files');if($method==='POST'&&$upload!==null){sv_require_permission($user,'SAFETY_VOTE_MANAGE');$id=sv_positive_int($upload['id']);$row=$id?sv_campaign_row($id):null;$file=$_FILES['file']??null;if(!$row)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);if($row['Status']!=='Draft')json_response(['success'=>false,'code'=>'CAMPAIGN_STATE_CONFLICT','message'=>'Files can be added only to Draft campaigns.'],409);if(!$file||(int)$file['error']!==UPLOAD_ERR_OK||(int)$file['size']>10*1024*1024)json_response(['success'=>false,'code'=>'FILE_UPLOAD_REJECTED','message'=>'A file not exceeding 10 MB is required.'],400);$mime=sv_file_mime((string)$file['tmp_name']);if(!$mime||!in_array($mime,['image/jpeg','image/png','image/webp','application/pdf'],true))json_response(['success'=>false,'code'=>'FILE_UPLOAD_REJECTED','message'=>'File content is not an allowed image or PDF.'],400);$ext=['image/jpeg'=>'.jpg','image/png'=>'.png','image/webp'=>'.webp','application/pdf'=>'.pdf'][$mime];$stored=time().'-'.bin2hex(random_bytes(18)).$ext;$target=sv_private_dir().DIRECTORY_SEPARATOR.$stored;if(!move_uploaded_file((string)$file['tmp_name'],$target))json_response(['success'=>false,'code'=>'FILE_UPLOAD_REJECTED','message'=>'Unable to store file.'],500);$sha=hash_file('sha256',$target);try{db_execute('INSERT INTO SafetyVote_Files(CampaignID,CampaignVersionID,FilePurpose,StoredName,OriginalName,MimeType,FileSize,ContentSha256,UploadedBy) VALUES(?,?,?,?,?,?,?,?,?)',[$id,$row['CurrentVersionID'],sv_clean($_POST['filePurpose']??'cover',40),$stored,sv_clean($file['name']??'',255),$mime,(int)$file['size'],$sha,sv_actor($user)]);$fileId=(int)db()->lastInsertId();}catch(Throwable$error){@unlink($target);throw$error;}sv_audit($user,'SAFETY_VOTE_FILE_UPLOAD','SafetyVote_File',(string)$fileId,'size='.(int)$file['size'],['mime'=>$mime,'sha256'=>$sha],$id,(int)$row['CurrentVersionID']);json_r