    $fileRoute=route_params($path,'/safety-vote/files/:fileId');if($method==='GET'&&$fileRoute!==null){sv_require_permission($user,'SAFETY_VOTE_VIEW');$id=sv_positive_int($fileRoute['fileId']);$file=$id?db_row("SELECT * FROM SafetyVote_Files WHERE id=? AND Status='Active' LIMIT 1",[$id]):null;if(!$file)json_response(['success'=>false,'code'=>'FILE_NOT_FOUND','message'=>'File was not found.'],404);if(sv_role($user)!=='ADMIN'&&!sv_has_permission($user,'SAFETY_VOTE_MANAGE')){$scope=db_row("SELECT e.id FROM SafetyVote_EligibilitySnapshots s JOIN SafetyVote_EligibleVoters e ON e.SnapshotID=s.id JOIN SafetyVote_Campaigns c ON c.CurrentVersionID=s.CampaignVersionID WHERE c.id=? AND s.Status='frozen' AND e.EmployeeID=? LIMIT 1",[$file['CampaignID'],sv_actor($user)]);if(!$scope)json_response(['success'=>false,'code'=>'FILE_NOT_FOUND','message'=>'File was not found.'],404);}$disk=sv_private_dir().DIRECTORY_SEPARATOR.basename((string)$file['StoredName']);if(!is_file($disk)||sv_file_mime($disk)!==$file['MimeType'])json_response(['success'=>false,'code'=>'FILE_NOT_FOUND','message'=>'File is unavailable.'],404);header('Content-Type: '.$file['MimeType']);header("Content-Disposition: inline; filename*=UTF-8''".rawurlencode((string)$file['OriginalName']));header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');readfile($disk);exit;}
